import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第二册：实践与进步 · Lesson 36 Across the Channel","description":"学习 将来进行时与过程，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 36 Across the Channel","description":"学习 将来进行时与过程，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 将来进行时与过程，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 35 Stop thief!","link":"/life/english/new-concept/book-2/unit-02/lesson-035"},"next":{"text":"第二册：实践与进步 · Lesson 37 The Olympic Games","link":"/life/english/new-concept/book-2/unit-02/lesson-037"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 35 Stop thief!","link":"/life/english/new-concept/book-2/unit-02/lesson-035"},"next":{"text":"第二册：实践与进步 · Lesson 37 The Olympic Games","link":"/life/english/new-concept/book-2/unit-02/lesson-037"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-036.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-036.md"}'),i={name:"life/english/new-concept/book-2/unit-02/lesson-036.md"};function l(s,e,r,h,c,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-36-across-the-channel" tabindex="-1">第二册：实践与进步 · Lesson 36 Across the Channel <a class="header-anchor" href="#第二册-实践与进步-·-lesson-36-across-the-channel" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 36 Across the Channel&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>长距离游泳需要分段补给与时间规划；练习预测某个未来时间点的活动状态。本课的语言观察是：will be swimming 指届时的过程，不保证成功到达；will have finished 才突出某时之前完成，但需要合理的计划或预测依据。完成学习后，请为一次长距离活动写时间计划，包括陪同者和停止条件。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>swim</td><td>/swɪm/</td><td>v.</td><td>游泳</td><td>swim across a pool</td></tr><tr><td>channel</td><td>/ˈtʃænəl/</td><td>n.</td><td>海峡；频道</td><td>cross the channel</td></tr><tr><td>coach</td><td>/kəʊtʃ/</td><td>n.</td><td>教练</td><td>a swimming coach</td></tr><tr><td>record</td><td>/ˈrekɔːd/</td><td>n.</td><td>纪录</td><td>break a record</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>set a record — 创立纪录</li><li>keep an eye on — 留意、照看，不能逐字译成把眼睛放上去</li></ul><h2 id="语法讲解-将来进行时与过程" tabindex="-1">语法讲解：将来进行时与过程 <a class="header-anchor" href="#语法讲解-将来进行时与过程" aria-label="Permalink to &quot;语法讲解：将来进行时与过程&quot;">​</a></h2><p>将来进行时使用 will be 加动词 -ing，突出未来某个时间正在发生的过程，常用于说明正常安排中的活动。它与 will do 的区别主要是观察角度：一个看过程，一个把动作看成整体。句中须有明确或可推知的未来参照时间。不要把 will be 后面接原形误当进行时，也不要用它保证某项活动一定完成；完成结果需要其他表达。本课应用：will be swimming 指届时的过程，不保证成功到达；will have finished 才突出某时之前完成，但需要合理的计划或预测依据。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>At noon tomorrow, Ava will be swimming near the eastern coast.</p></blockquote><p>明天中午，艾娃将在东海岸附近游泳。</p><p>will be swimming 是将来进行时，At noon tomorrow 给出参照时点，near 表示附近而非已经上岸。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>will be swum 是被动形式，不表示她自己正在游；此处用 swimming。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对比 swimming 的短元音与 coast 的双元音；重读 at noon。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>At noon tomorrow, Ava will be swimming near the eastern coast. Her coach will follow in a boat. They will stop if the weather becomes dangerous.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为一次长距离活动写时间计划，包括陪同者和停止条件。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：will be swimming 是将来进行时，At noon tomorrow 给出参照时点，near 表示附近而非已经上岸。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：will be swum 是被动形式，不表示她自己正在游；此处用 swimming。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 swim 的形式：Ava will be ___ at noon.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> swimming</p><p><strong>解析：</strong> 进行时用 -ing，swim 双写 m。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>天气危险时他们会怎样？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> They will stop.</p><p><strong>解析：</strong> 真实条件句表明停止条件，并非保证一定遇到危险。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>补全：They will stop if the weather ___ dangerous.（become）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> becomes</p><p><strong>解析：</strong> if 条件从句用现在时，weather 是单数不可数名词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：将来进行时与过程。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-035">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-037">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=a(i,[["render",l]]);export{m as __pageData,u as default};
